/**
 * Exo TRISOLV driver: mirrors PolyBench/C trisolv.c but calls the Exo-generated kernel.
 */

#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "trisolv.h"

/* Include the Exo-generated kernel header. */
#include "generated/trisolv/trisolv.h"


/* Array initialization. */
static
void init_array(int n,
		DATA_TYPE POLYBENCH_2D(L,N,N,n,n),
		DATA_TYPE POLYBENCH_1D(x,N,n),
		DATA_TYPE POLYBENCH_1D(b,N,n))
{
  int i, j;

  for (i = 0; i < n; i++)
    {
      x[i] = - 999;
      b[i] =  i ;
      for (j = 0; j <= i; j++)
	L[i][j] = (DATA_TYPE) (i+n-j+1)*2/n;
    }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_1D(x,N,n))

{
  int i;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("x");
  for (i = 0; i < n; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, x[i]);
  }
  POLYBENCH_DUMP_END("x");
  POLYBENCH_DUMP_FINISH;
}

/* Kernel implementation in Exo:
EXO START
from __future__ import annotations

from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM

# Tunable compile-time constant controlling inner-loop blocking.
# Adjust BLOCK_J (e.g., 16, 32, 64) to match the target cache/microarchitecture.
BLOCK_J: int = 32

@proc
def kernel_trisolv_base(
    n: size,
    L: DATA_TYPE[n, n] @ DRAM,
    x: DATA_TYPE[n] @ DRAM,
    b: DATA_TYPE[n] @ DRAM,
):
    # Forward substitution for a lower-triangular system L x = b.
    # We express the inner computation as an explicit dot product
    # to expose a pure reduction that can be safely transformed.
    for i in seq(0, n):
        # Accumulate sum_{j=0..i-1} L[i,j] * x[j] into a scalar.
        tmp: DATA_TYPE
        tmp = 0.0
        for j in seq(0, i):
            tmp += L[i, j] * x[j]
        # This is algebraically equivalent to the original:
        #   x[i] = b[i]
        #   for j in 0..i-1: x[i] -= L[i,j] * x[j]
        #   x[i] /= L[i,i]
        x[i] = (b[i] - tmp) / L[i, i]

# Create an optimized kernel by applying scheduling transformations
# to the mathematically equivalent base implementation.
kernel_trisolv = kernel_trisolv_base

# 1) Tile the inner j loop by BLOCK_J.
#    This improves instruction-level parallelism and prepares the loop
#    for aggressive unrolling while preserving the dependence structure
#    along the i dimension.
j_loop = kernel_trisolv.find_loop("j")
kernel_trisolv = divide_loop(kernel_trisolv, j_loop, BLOCK_J, ("jb", "jj"), tail="cut")

# After this transformation, for each i we conceptually have:
#   for jb in seq(0, i / BLOCK_J):
#       for jj in seq(0, BLOCK_J):
#           j = BLOCK_J * jb + jj
#           ...
#   for jj in seq(0, i - BLOCK_J * (i / BLOCK_J)):
#       j = BLOCK_J * (i / BLOCK_J) + jj
#       ...
# The second jj loop handles the (usually short) tail.

# 2) Fully unroll the constant-bounded inner jj loop corresponding to
#    the full tiles (BLOCK_J iterations). This exposes a straight-line
#    sequence of fused multiply-adds, which modern compilers can map
#    efficiently to vector/FMA instructions.
jj_full = kernel_trisolv.find_loop("jj")
kernel_trisolv = unroll_loop(kernel_trisolv, jj_full)

# 3) Simplify the resulting expressions and loop bounds.
kernel_trisolv = simplify(kernel_trisolv)
EXO END
*/


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(L, DATA_TYPE, N, N, n, n);
  POLYBENCH_1D_ARRAY_DECL(x, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(b, DATA_TYPE, N, n);


  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(L), POLYBENCH_ARRAY(x), POLYBENCH_ARRAY(b));

  /* Start timer. */
  polybench_start_instruments;

  /* Run Exo kernel. Flatten views to raw pointers. */
  kernel_trisolv (/*ctxt=*/NULL,
                  n,
                  (DATA_TYPE*)POLYBENCH_ARRAY(L),
                  (DATA_TYPE*)POLYBENCH_ARRAY(x),
                  (DATA_TYPE*)POLYBENCH_ARRAY(b));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(x)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(L);
  POLYBENCH_FREE_ARRAY(x);
  POLYBENCH_FREE_ARRAY(b);

  return 0;
}
